CREATE TABLE IF NOT EXISTS `one_sgod_risk_opportunity_monitoring` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`section_name` VARCHAR(255) NOT NULL,`sec_group` VARCHAR(50) NOT NULL DEFAULT 'SGOD',`username` VARCHAR(255) NOT NULL,`monitoring_date` DATE NOT NULL,`item_type` VARCHAR(20) NOT NULL,`statement` TEXT NOT NULL,`before_rating` TINYINT UNSIGNED NOT NULL,`after_rating` TINYINT UNSIGNED NOT NULL,`status` VARCHAR(20) NOT NULL,`explanation` TEXT NULL,`recommendation` TEXT NULL,`created_at` DATETIME NOT NULL,`updated_at` DATETIME NULL,PRIMARY KEY(`id`),KEY `idx_section_date` (`section_name`,`sec_group`,`monitoring_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
